    const unsigned char* data, size_t data_len
) {
    encryption_result result;
    result.encrypted_data = NULL;
    result.iv = NULL;
    result.key = NULL;

    // Determine the AES key length (16 bytes for AES-128, 24 for AES-192, 32 for AES-256)
    size_t aes_key_length = 16; // Default to AES-128
    if (key_len >= 32) {
        aes_key_length = 32; // Use AES-256 if possible
    } else if (key_len >= 24) {
        aes_key_length = 24; // Use AES-192 if possible
    }

    // Allocate memory for the key
    result.key = (unsigned char*)malloc(aes_key_length);
    if (!result.key) {
        return result;
    }
    memcpy(result.key, key, aes_key_length);

    // Allocate memory for the IV
    result.iv = (unsigned char*)malloc(AES_BLOCK_SIZE);
    if (!result.iv) {
        free(result.key);
        return result;
    }
    if (!RAND_bytes(result.iv, AES_BLOCK_SIZE)) {
        free(result.key);
        free(result.iv);
        return result;
    }

    // Create and initialize the AES context
    AES_KEY encrypt_key;
    if (AES_set_encrypt_key(result.key, aes_key_length * 8, &encrypt_key) < 0) {
        free(result.key);
        free(result.iv);
        return result;
    }

    // Calculate the length of the padded data
    size_t padded_data_len = ((data_len + AES_BLOCK_SIZE - 1) / AES_BLOCK_SIZE) * AES_BLOCK_SIZE;
    result.encrypted_data = (unsigned char*)malloc(padded_data_len);
    if (!result.encrypted_data) {
        free(result.key);
        free(result.iv);
        return result;
    }

    // Pad the data
    unsigned char* padded_data = (unsigned char*)malloc(padded_data_len);
    if (!padded_data) {
        free(result.key);
        free(result.iv);
        free(result.encrypted_data);
        return result;
    }
    memcpy(padded_data, data, data_len);
    memset(padded_data + data_len, padded_data_len - data_len, padded_data_len - data_len);

    // Encrypt the data
    AES_cbc_encrypt(padded_data, result.encrypted_data, padded_data_len, &encrypt_key, result.iv, AES_ENCRYPT);

    // Set the encrypted length
    result.encrypted_len = padded_data_len;

    // Free the padded data
    free(padded_data);

    // Securely clear sensitive data
    memset(encrypt_key.rd_key, 0, sizeof(encrypt_key.rd_key));

    return result;
}
